from collections.abc import Mapping


def render_label(base, attributes, suppressed=()):
    if not isinstance(base, str):
        raise TypeError("base must be a string")
    if not isinstance(attributes, Mapping):
        raise TypeError("attributes must be a mapping")
    if any(not isinstance(key, str) for key in attributes):
        raise TypeError("attribute keys must be strings")
    hidden = list(suppressed)
    if any(not isinstance(key, str) for key in hidden):
        raise TypeError("suppressed keys must be strings")
    for key in hidden:
        attributes.pop(key, None)
    if not attributes:
        return base
    details = ", ".join(
        key + "=" + repr(attributes[key]) for key in sorted(attributes)
    )
    return base + " [" + details + "]"
