import unittest
from collections import OrderedDict
from types import MappingProxyType

from solution import render_label


class RenderLabelTests(unittest.TestCase):
    def test_sorted_formatting_uses_repr(self):
        attributes = OrderedDict([("z", "text"), ("a", 3), ("middle", None)])
        self.assertEqual(render_label("item", attributes), "item [a=3, middle=None, z='text']")

    def test_suppression_duplicates_and_absent_keys(self):
        attributes = {"a": 1, "b": 2, "c": 3}
        self.assertEqual(render_label("x", attributes, ["b", "b", "missing"]), "x [a=1, c=3]")
        self.assertEqual(render_label("x", attributes, (key for key in ["a", "c"])), "x [b=2]")

    def test_no_visible_attributes_returns_base_unchanged(self):
        base = "plain"
        self.assertIs(render_label(base, {}), base)
        self.assertEqual(render_label(base, {"a": 1}, ["a"]), base)

    def test_inputs_and_nested_values_are_not_mutated(self):
        nested = {"items": [1, 2]}
        attributes = {"keep": nested, "hide": [3]}
        suppressed = ["hide"]
        result = render_label("x", attributes, suppressed)
        self.assertEqual(result, "x [keep={'items': [1, 2]}]")
        self.assertEqual(attributes, {"keep": {"items": [1, 2]}, "hide": [3]})
        self.assertIs(attributes["keep"], nested)
        self.assertEqual(suppressed, ["hide"])
        self.assertIsInstance(result, str)

    def test_read_only_mapping_supported(self):
        attributes = MappingProxyType({"b": 2, "a": 1})
        self.assertEqual(render_label("x", attributes, ["b"]), "x [a=1]")
        self.assertEqual(dict(attributes), {"b": 2, "a": 1})

    def test_invalid_base_and_mapping(self):
        for base in [None, b"x", 4]:
            with self.subTest(base=base):
                with self.assertRaises(TypeError):
                    render_label(base, {})
        for attributes in [None, [], [("a", 1)]]:
            with self.subTest(attributes=attributes):
                with self.assertRaises(TypeError):
                    render_label("x", attributes)

    def test_invalid_attribute_keys_rejected_before_formatting(self):
        class BadRepr:
            def __repr__(self):
                raise AssertionError("formatting must not start")

        with self.assertRaises(TypeError):
            render_label("x", {"valid": BadRepr(), 3: "bad"})

    def test_invalid_suppressed_entries_rejected_before_formatting(self):
        class BadRepr:
            def __repr__(self):
                raise AssertionError("formatting must not start")

        attributes = {"a": BadRepr()}
        with self.assertRaises(TypeError):
            render_label("x", attributes, ["a", 3])
        self.assertIn("a", attributes)
        with self.assertRaises(TypeError):
            render_label("x", attributes, None)


if __name__ == "__main__":
    unittest.main()

